int qmdl_vertex_normal_is_valid(qmdl_u8 normal_index)
{
    return (normal_index < QMDL_NUM_VERTEX_NORMALS) ? 1 : 0;
}

int qmdl_get_vertex_normal_fx16(qmdl_u8 normal_index,
                                qmdl_fx16 out_xyz[3])
{
    if (out_xyz == 0)
    {
        return QMDL_ERR_ARGS;
    }
    if (!qmdl_vertex_normal_is_valid(normal_index))
    {
        return QMDL_ERR_RANGE;
    }
    out_xyz[0] = ((qmdl_fx16)qmdl_vertex_normals_q14[normal_index][0]) << 2;
    out_xyz[1] = ((qmdl_fx16)qmdl_vertex_normals_q14[normal_index][1]) << 2;
    out_xyz[2] = ((qmdl_fx16)qmdl_vertex_normals_q14[normal_index][2]) << 2;
    return QMDL_OK;
}

static qmdl_i16 qmdl_fx16_to_q14(qmdl_fx16 value)
{
    qmdl_i32 rounded;
    if (value >= 0)
    {
        rounded = (value + 2) >> 2;
    }
    else
    {
        rounded = -(((-value) + 2) >> 2);
    }
    if (rounded > 32767) rounded = 32767;
    if (rounded < -32768) rounded = -32768;
    return (qmdl_i16)rounded;
}

qmdl_u8 qmdl_find_nearest_vertex_normal_fx16(const qmdl_fx16 in_xyz[3])
{
    qmdl_i16 x;
    qmdl_i16 y;
    qmdl_i16 z;
    qmdl_i32 best_dot;
    qmdl_u32 i;
    qmdl_u8 best_index;

    if (in_xyz == 0)
    {
        return 0u;
    }

    x = qmdl_fx16_to_q14(in_xyz[0]);
    y = qmdl_fx16_to_q14(in_xyz[1]);
    z = qmdl_fx16_to_q14(in_xyz[2]);

    best_dot = ((qmdl_i32)x * (qmdl_i32)qmdl_vertex_normals_q14[0][0]) +
               ((qmdl_i32)y * (qmdl_i32)qmdl_vertex_normals_q14[0][1]) +
               ((qmdl_i32)z * (qmdl_i32)qmdl_vertex_normals_q14[0][2]);
    best_index = 0u;

    for (i = 1u; i < QMDL_NUM_VERTEX_NORMALS; ++i)
    {
        qmdl_i32 dot;
        dot = ((qmdl_i32)x * (qmdl_i32)qmdl_vertex_normals_q14[i][0]) +
              ((qmdl_i32)y * (qmdl_i32)qmdl_vertex_normals_q14[i][1]) +
              ((qmdl_i32)z * (qmdl_i32)qmdl_vertex_normals_q14[i][2]);
        if (dot > best_dot)
        {
            best_dot = dot;
            best_index = (qmdl_u8)i;
        }
    }

    return best_index;
}